import { defineCollection } from 'astro:content';
import { file, glob } from 'astro/loaders';
import { z } from 'astro/zod';

/**
 * Content schemas + loaders (data layer, Astro 7 content collections).
 *
 * Schemas are exported as values so domain types can be derived with
 * z.infer — no parallel interfaces anywhere (single source of truth).
 * The `id` of each entry is generated by Astro, not declared here.
 *
 * Content rule (docs/project/CONTENT_GUIDELINES): never invent artist data.
 * Optional fields stay optional; provisional values are marked in the JSON
 * themselves ("artwork identification pending", etc.).
 */

export const homeSchema = z
  .object({
    slideshow: z
      .array(
        z.object({
          image: z.string(),
          width: z.number().int().positive(),
          height: z.number().int().positive(),
          alt: z.string(),
          href: z.string().default('/work'),
        }),
      )
      .max(6),
  })
  .describe('Home slideshow entries');

export const profileSchema = z
  .object({
    name: z.string(),
    location: z.string().optional(),
    // Verified public contact (docs/project/CONTENT_GUIDELINES)
    email: z.string(),
    instagram: z.string(),
    biography: z.string().optional(),
    artistStatement: z.string().optional(),
    portrait: z.string().optional(),
    cv: z.string().optional(),
  })
  .describe('Artist profile singleton');

export const artworkSchema = z
  .object({
    title: z.string().optional(), // pending confirmation against the dossier — never invent
    image: z.string(),
    year: z.string().optional(),
    dimensions: z.string().optional(),
    technique: z.string().optional(),
    caption: z.string().optional(),
    alt: z.string(), // REQUIRED for every artwork
    order: z.number().int().default(0),
  })
  .describe('Artwork embedded in a Project (1:N)');

export const projectSchema = z
  .object({
    title: z.string().optional(), // pending confirmation — never invent
    year: z.string().optional(),
    discipline: z.enum(['photography', 'sculpture', 'video']),
    coverImage: z.string(),
    description: z.string().optional(),
    artistStatement: z.string().optional(),
    artworks: z.array(artworkSchema).default([]),
    credits: z.string().optional(),
    displayOrder: z.number().int().default(0),
    status: z.enum(['published', 'draft']).default('draft'),
    featured: z.boolean().default(false),
  })
  .describe('Work project');

export const pressSchema = z
  .object({
    publication: z.string(),
    title: z.string(),
    date: z.coerce.date().optional(),
    author: z.string().optional(),
    type: z.string().optional(),
    description: z.string().optional(),
    externalUrl: z.url(),
  })
  .describe('Press mention');

export const exhibitionSchema = z
  .object({
    title: z.string(),
    kind: z.enum(['solo', 'group']),
    venue: z.string(),
    city: z.string().optional(),
    country: z.string().optional(),
    dates: z.string().optional(),
    curator: z.string().optional(),
    description: z.string().optional(),
    images: z.array(z.string()).default([]),
  })
  .describe('Exhibition record');

const home = defineCollection({
  loader: file('./src/content/home.json'),
  schema: homeSchema,
});

const profile = defineCollection({
  loader: file('./src/content/profile.json'),
  schema: profileSchema,
});

const projects = defineCollection({
  loader: glob({ base: './src/content/projects', pattern: '*.json' }),
  schema: projectSchema,
});

const press = defineCollection({
  loader: glob({ base: './src/content/press', pattern: '*.json' }),
  schema: pressSchema,
});

const exhibitions = defineCollection({
  loader: glob({ base: './src/content/exhibitions', pattern: '*.json' }),
  schema: exhibitionSchema,
});

export const collections = { home, profile, projects, press, exhibitions };
